#[derive(Clone)]
struct Player { position: [f32; 3], velocity: [f32; 3] }
struct Arena { size: [f32; 3] }

fn main() {
    let mut players = vec![Player { position: [0., 0., 0.], velocity: [0., 0., 0.] }; 1];
    let arena = Arena { size: [100., 100., 100.] };

    for _ in 0..10 {
        update_physics(&mut players, &arena);
        if check_first_blood(&players[0]) {
            log_achievement("First Blood");
        }
    }
}

fn update_physics(players: &mut [Player], arena: &Arena) {
    const GRAVITY: f32 = -9.81;
    const JUMP_IMPULSE: f32 = 10.;
    const DT: f32 = 1. / 60.; // 60 Hz

    for player in players.iter_mut() {
        player.velocity[1] += GRAVITY * DT;
        player.position[1] += player.velocity[1] * DT;

        if player.position[1] <= 0. && player.velocity[1] < 0. {
            player.velocity[1] = -player.velocity[1] + JUMP_IMPULSE;
        }

        // Simple collision detection with the floor
        if player.position[1] < 0. {
            player.position[1] = 0.;
            player.velocity[1] = 0.;
        }

        // Basic boundary checking
        for i in 0..3 {
            if player.position[i] > arena.size[i] || player.position[i] < 0. {
                player.position[i] = arena.size[i] / 2.;
                player.velocity[i] = 0.;
            }
        }
    }
}

fn check_first_blood(player: &Player) -> bool {
    // Simplified condition to unlock "First Blood"
    player.position[1] > 5.
}

fn log_achievement(achievement_name: &str) {
    println!("Achievement unlocked: {}", achievement_name);
}

