        self.position.0 += self.velocity.0 * dt;
        self.position.1 += self.velocity.1 * dt;

        if self.coyote_timer > 0.0 {
            self.coyote_timer -= dt;
        }

        if self.dash_cooldown_timer > 0.0 {
            self.dash_cooldown_timer -= dt;
        }
