        if self.dash_cooldown_timer <= 0.0 {
            self.velocity.0 += direction.0 * GRAPPLE_SPEED;
            self.velocity.1 += direction.1 * GRAPPLE_SPEED;
            self.dash_cooldown_timer = DASH_COOLDOWN;
