    #[test]
    fn test_sphere_pillar_collision() {
        let sphere = Sphere {
            position: (0.0, 0.0, 0.0),
            radius: 1.0,
        };

        let pillar = Pillar {
            position: (1.0, 0.0, 0.0),
            radius: 1.0,
            height: 10.0,
        };

        assert!(sphere_pillar_collision(&sphere, &pillar));
    }

